        }
        is FfiTimelineItem.TimelineStart -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FfiTimelineItem, buf: ByteBuffer) {
        when(value) {
            is FfiTimelineItem.Event -> {
                buf.putInt(1)
                FfiConverterString.write(value.`uniqueId`, buf)
                FfiConverterOptionalString.write(value.`eventId`, buf)
                FfiConverterULong.write(value.`threadReplies`, buf)
                FfiConverterSequenceTypeFfiReaction.write(value.`reactions`, buf)
                FfiConverterOptionalTypeFfiInReplyTo.write(value.`inReplyTo`, buf)
                FfiConverterBoolean.write(value.`isEdited`, buf)
                FfiConverterSequenceString.write(value.`receipts`, buf)
                FfiConverterString.write(value.`sender`, buf)
                FfiConverterOptionalString.write(value.`senderDisplayName`, buf)
                FfiConverterULong.write(value.`timestamp`, buf)
                FfiConverterBoolean.write(value.`isOwn`, buf)
                FfiConverterTypeFfiEventKind.write(value.`kind`, buf)
                FfiConverterString.write(value.`body`, buf)
                FfiConverterSequenceTypeFfiRichBlock.write(value.`rich`, buf)
                FfiConverterOptionalTypeFfiShield.write(value.`shield`, buf)
                FfiConverterOptionalTypeFfiSendState.write(value.`sendState`, buf)
                Unit
            }
            is FfiTimelineItem.DateDivider -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`timestamp`, buf)
                Unit
            }
            is FfiTimelineItem.ReadMarker -> {
                buf.putInt(3)
                Unit
            }
            is FfiTimelineItem.TimelineStart -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Whether this session itself is verified.
 */

enum class FfiVerificationState {
    
    /**
     * Not known yet.
     */
    UNKNOWN,
    /**
     * This session is verified.
     */
    VERIFIED,
    /**
     * This session is not verified.
     */
    UNVERIFIED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiVerificationState: FfiConverterRustBuffer<FfiVerificationState> {
    override fun read(buf: ByteBuffer) = try {
        FfiVerificationState.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiVerificationState) = 4UL

    override fun write(value: FfiVerificationState, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






